import{_ as a,c as s,o as n,ag as r}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Signal Welcome Prompts","description":"","frontmatter":{"title":"Signal Welcome Prompts"},"headers":[],"relativePath":"community/signal-welcome-prompts.md","filePath":"community/signal-welcome-prompts.md","lastUpdated":null}'),t={name:"community/signal-welcome-prompts.md"};function i(o,e,p,l,c,u){return n(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="signal-welcome-prompts" tabindex="-1">Signal Welcome Prompts <a class="header-anchor" href="#signal-welcome-prompts" aria-label="Permalink to &quot;Signal Welcome Prompts&quot;">​</a></h1><p>Admin Signal Welcome Prompts For Admin, See the <a href="https://mod.irregular.chat" target="_blank" rel="noreferrer">Mod Portal</a> to create users and more</p><ul><li><p>Back to main <a href="/general/admin.html">page</a></p></li><li><p><a href="/general/links.html">Links</a> with all the chats</p></li><li><p><a href="/community/welcome.html">Page</a></p></li><li><p><a href="https://forum.irregularchat.com" target="_blank" rel="noreferrer">IrregularChat Forum</a></p></li></ul><h3 id="ask-individuals-to-introduce-themselves" tabindex="-1">Ask Individuals to Introduce Themselves <a class="header-anchor" href="#ask-individuals-to-introduce-themselves" aria-label="Permalink to &quot;Ask Individuals to Introduce Themselves&quot;">​</a></h3><h3 id="tech-chat" tabindex="-1">Tech Chat <a class="header-anchor" href="#tech-chat" aria-label="Permalink to &quot;Tech Chat&quot;">​</a></h3><p><a href="/community/community-recommended-pathways.html">Recommended Pathways</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🚀 Welcome to the Tech Chat! 🚀</span></span>
<span class="line"><span></span></span>
<span class="line"><span>As you join us, please take a moment to browse the user list and introduce yourself. We&#39;re excited to learn about your tech training, interests, and projects. This is a great opportunity to self-promote and share your tech projects or ask a question to the community.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Resources for Learning: Check out some fantastic resources shared within our group at https://irregularpedia.org/general/learning</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Expectation Management: This group fosters a focused environment for general tech discussions. Off-topic banter is directed to our Off-Topic Chat, where you can freely share and enjoy less technical content. This approach helps us maintain the quality and relevance of discussions for everyone&#39;s benefit.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Thank you for joining us, and we look forward to your contributions!</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="influence-chat" tabindex="-1">Influence Chat <a class="header-anchor" href="#influence-chat" aria-label="Permalink to &quot;Influence Chat&quot;">​</a></h3><p><a href="/general/national-strategy-and-reports.html">Strategy and Reports</a>\`\`\`</p><p>🚀 Welcome to the Influence Chat! 🚀 Please take a moment to look around and introduce yourself to the group.</p><p>We love reading articles, dissertations, and white papers on influence, behavior change models, social movements, and related studies or news; please share something with the group.</p><p>Check out some resources for learning shared with the group: <a href="https://irregularpedia.org/general/learning" target="_blank" rel="noreferrer">https://irregularpedia.org/general/learning</a></p><p>National Strategic Documents and Reports: <a href="https://irregularpedia.org/general/national-strategy-and-reports" target="_blank" rel="noreferrer">https://irregularpedia.org/general/national-strategy-and-reports</a></p><p>See all the community chats: <a href="https://forum.irregularchat.com/t/229" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/229</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Innovation Chat</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#### Innovation Bonafide</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>You requested to join the innovation chat. Are you currently in a unit supporting 1SFC or USASOC? All chat members have been validated.</p><p>Your request will be rejected if you don&#39;t reply to this message in 24 hours. You can request again when you are ready.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>#### Innovation Greeting</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>🚀 Welcome to the unofficial 1SFC/USASOC Innovation Chat! 🚀 The chat is focused on innovative efforts that directly benefit the command and units; see the group description for more information.</p><p>Please take a moment to introduce yourself and include at least the following:</p><h2 id="what-innovative-projects-are-you-or-your-unit-currently-exploring" tabindex="-1">What innovative projects are you or your unit currently exploring? <a class="header-anchor" href="#what-innovative-projects-are-you-or-your-unit-currently-exploring" aria-label="Permalink to &quot;What innovative projects are you or your unit currently exploring?&quot;">​</a></h2><ol start="2"><li>Have you identified capability gaps that might impact your unit or mission?</li><li>How do you understand the process for submitting innovation requirements?</li></ol><p>Beyond daily engagement, we’d now love to hear from you or others who may want to collaborate with your efforts.</p><p>Please remember that this chat is strictly for unclassified discussions. For CUI SOCOM Teams: <a href="https://go.intellink.gov/1sfc_g8" target="_blank" rel="noreferrer">https://go.intellink.gov/1sfc_g8</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Research &amp;amp; Data Chat</span></span>
<span class="line"><span>[Page](/research/)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>🧐 Welcome to the Research Chat! 📚 Share some of your relative research background, interests in research, and research projects! What are you currently researching, and how can we help?</p><p>Remember the forum is unclassified, and use any DM for advanced sharing of PII and contact information. Help Expand the known resources by reviewing: <a href="https://irregularpedia.org/research/" target="_blank" rel="noreferrer">https://irregularpedia.org/research/</a></p><p>Let us know what sections or resources should be included for research and planning.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>### AI/ML Chat</span></span>
<span class="line"><span>[chat page](/ai-ml/ai-resources)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>📊 Welcome to the AI/ML Chat! 🤖 Share your relevant background, interests, and AI/ML/DATA projects!</p><p>Remember, the forum is unclassified, so use any DM to share PII and contact information in advance. Help Expand the knowledge base on the wiki: AI/ML Wiki - <a href="https://irregularpedia.org/ai-ml/" target="_blank" rel="noreferrer">https://irregularpedia.org/ai-ml/</a> AI/ML Forum: <a href="https://forum.irregularchat.com/tag/ai" target="_blank" rel="noreferrer">https://forum.irregularchat.com/tag/ai</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>### DragonOS Chat</span></span>
<span class="line"><span>[chat page](/radio/dragonos)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>🐉 Welcome to the DragonOS Chat! 🐉 Feel free to ask questions, provide feedback, or just lurk. Please introduce yourself and let us know how you use DragonOS in your hobbies or work. Which SDR do you currently own?</p><ul><li>YouTube channel: <a href="https://youtube.com/@cemaxecuter7783/" target="_blank" rel="noreferrer">https://youtube.com/@cemaxecuter7783/</a></li><li>X: <a href="https://twitter.com/cemaxecuter/" target="_blank" rel="noreferrer">https://twitter.com/cemaxecuter/</a></li><li>Download ISO: <a href="https://sourceforge.net/u/cemaxecuter/profile/" target="_blank" rel="noreferrer">https://sourceforge.net/u/cemaxecuter/profile/</a></li><li>Wiki Section: <a href="https://irregularpedia.org/radio/dragonos" target="_blank" rel="noreferrer">https://irregularpedia.org/radio/dragonos</a></li></ul><p>See all the community chats: <a href="https://forum.irregularchat.com/t/229" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/229</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### SPACE Chat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>🚀 Welcome to the Space Capabilities &amp; Innovation Chat! 🌌</p><p>This group is dedicated to unclassified discussions on space capabilities, technology, news, and strategic developments. Whether you’re interested in unclassified discussions of orbital warfare, ISR advancements, commercial space integration, or space-based communications, this is the place to stay informed, collaborate, and share insights. 📚 Space Capabilities Wiki: <a href="https://irregularpedia.org/general/" target="_blank" rel="noreferrer">https://irregularpedia.org/general/</a> 🌍 Community Forum: <a href="https://forum.irregularchat.com/tag/space" target="_blank" rel="noreferrer">https://forum.irregularchat.com/tag/space</a> 📁 Unclassified Files shared in the chat: <a href="https://u.pcloud.link/publink/show?code=kZ7qV85ZwCUR8nO0Lsj6VyzdJTu9XFR6BBMV" target="_blank" rel="noreferrer">https://u.pcloud.link/publink/show?code=kZ7qV85ZwCUR8nO0Lsj6VyzdJTu9XFR6BBMV</a></p><p>🛰️ Get Involved! • Introduce yourself – What’s your background or interest in space? • Share news &amp; research – Relevant articles, white papers, and space-related reports. • Organize &amp; connect – If you’re involved in space-related initiatives, drop your details and engage with the community.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>### sUAS - Unmanned Systems Chat - Drones and Robotics</span></span>
<span class="line"><span>[Systems chat page](/general/unmanned-systems)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>🤖 Welcome to the Unmanned Systems Chat! 🚁 Welcome to the chat. Please share some of your relative background, interests, and projects with the community of hobbyists chatting in their free time.</p><p>Remember, the forum is unclassified, unaffiliated to any organization, and not limited to USG or DOD.</p><p>Resources, Guides, and precious gems from the conversation can be found and edited here. Learn about the community before jumping in. <a href="https://irregularpedia.org/general/unmanned-systems" target="_blank" rel="noreferrer">https://irregularpedia.org/general/unmanned-systems</a></p><p>Previously shared files are found here - <a href="https://url.irregular.chat/unmanned-drive" target="_blank" rel="noreferrer">https://url.irregular.chat/unmanned-drive</a> the password, with spaces, is:</p><p>Anymore01!@Shadow01!@Unkempt</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Counter UxS: Countering Uncrewed Systems</span></span>
<span class="line"><span>[ Counter UxS Wiki Page](/general/counter-uxs)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>🚀 Welcome to the C-UxS Chat! 🚀 Please take a moment to look around and introduce yourself to the group.</p><p>We are here because we love stopping and breaking drones, monitoring advances on the emerging threat from red unmanned systems, from real cutting-edge technologies to modeling and simulation for the counter perspective of air, sea, land, sub-sea, and space. Please share something with the group.</p><p>See all the community chats: <a href="https://forum.irregularchat.com/t/229" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/229</a></p><p>Previously shared files are found here - <a href="https://url.irregular.chat/cuxs-drive" target="_blank" rel="noreferrer">https://url.irregular.chat/cuxs-drive</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Fabrication</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>⚙️ Welcome to the Fabrication Chat! 🛠️</p><p>Jump in and share your fabrication skills, projects, and questions, from 3D printing to metalwork! Start by introducing yourself and your projects.</p><p>📝 : Help grow our knowledge base! Add to the Fabrication Wiki at irregularpedia.org/general/3d-printer-recommendation or contribute to the NIPR Inteldocs at go.intelink.gov/I7IjyTL.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Off-Topic Chat</span></span>
<span class="line"><span>[Off Topic Forum](https://forum.irregularchat.com/c/off-topic-guild/5)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>If it&#39;s you&#39;re first day in off-topic chat, you gotta meme.</p><p>Beyond memes, this is open to creative discussion, gaming, venting, successes and failures, and back and forths, not focused on tech, influence, research, or other focused themes.</p><p>Nothing Illegal, Classified, or Unethical is allowed, but as you&#39;ll see, there is still a lot of room for fun.</p><p>See all the community chats: <a href="https://forum.irregularchat.com/t/229" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/229</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Purple Teaming Chat</span></span>
<span class="line"><span>[Teaming Chat DFP Guide](/cybersecurity/cyber-red-teaming)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Guide](/general/dfp-guide)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>🗡️ Welcome to the Purple Team Community Chat! 🛡️🕵️‍♂️</p><ul><li>Introduce Yourself: Tell us about your experience and what draws you to red or blue teaming.</li><li>Share and Learn: Utilize the wiki to access and contribute to our growing list of resources and guides.</li><li>Engage: Share information on upcoming workshops, events, and your red teaming projects. Please remember that all discussions here should remain within consensual boundaries and be suitable for an unclassified forum.</li></ul><p>Which is your interest? Red Team:</p><ul><li><a href="https://irregularpedia.org/cybersecurity/cyber-red-teaming" target="_blank" rel="noreferrer">https://irregularpedia.org/cybersecurity/cyber-red-teaming</a> Blue Team:</li><li><a href="https://irregularpedia.org/general/dfp-guide" target="_blank" rel="noreferrer">https://irregularpedia.org/general/dfp-guide</a></li><li><a href="https://irregularpedia.org/cybersecurity/cyber-incident-response-guide-personal" target="_blank" rel="noreferrer">https://irregularpedia.org/cybersecurity/cyber-incident-response-guide-personal</a></li></ul><p>See all the community chats: <a href="https://forum.irregularchat.com/t/229" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/229</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Business Chat</span></span>
<span class="line"><span>[chat page](/general/business)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Welcome to the Business Chat, a specialized haven for service members and veterans navigating the civilian business landscape.</p><p>Introduce yourself, share your experiences, and outline your aspirations. For archived resources, connections, and opportunities, visit <a href="https://irregularpedia.org/general/business" target="_blank" rel="noreferrer">https://irregularpedia.org/general/business</a>.</p><p>Previous intros can be found here: <a href="https://forum.irregularchat.com/t/business-chat-introductions/100" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/business-chat-introductions/100</a></p><p>To maintain the community&#39;s essence, avoid spam or excessive promotions</p><p>See all the community chats: <a href="https://forum.irregularchat.com/t/229" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/229</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Cert Chat</span></span>
<span class="line"><span>[chat page](/general/certifications)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>📚 To kickstart or enhance your journey, we&#39;ve compiled various resources. Whether you&#39;re new or seasoned, these will surely add value:</p><ul><li>General Learning Resources: <a href="https://irregularpedia.org/general/learning" target="_blank" rel="noreferrer">https://irregularpedia.org/general/learning</a></li><li>Guides and Resources for Certification Pathways: <a href="https://irregularpedia.org/general/certifications" target="_blank" rel="noreferrer">https://irregularpedia.org/general/certifications</a></li></ul><p>💬 Introduce yourself! Share what certifications you&#39;re pursuing, your learning methods, and any questions or insights.</p><p>See all the community chats: <a href="https://forum.irregularchat.com/t/229" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/229</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Debate Chat</span></span>
<span class="line"><span>[chat page](/general/debate)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ol><li>State Your Initial Position: Brief and Clear. Max Two Sentences.</li><li>Create an Ephemeral Notepad and Post the Link:<a href="https://cryptpad.irregularchat.com/pad/#/2/pad/view/+Hi8ffnuvn+ULb5FfNVSTKfiBiDX02d0Hylx7YHxxHo/" target="_blank" rel="noreferrer">https://cryptpad.irregularchat.com/pad/#/2/pad/view/+Hi8ffnuvn+ULb5FfNVSTKfiBiDX02d0Hylx7YHxxHo/</a></li><li>Open the Floor for Questions and join Sides from ALL.</li><li>10-Minute Argument Submission: post your argument Supporting your position.</li><li>Sides are defined. Only participants can ask questions beyond this point.</li><li>Respectful Debate: • Provide emoji to show support, questions, and objection • Only those with a stated position may make arguments. All can ask questions that can be direct but may be answered by either party. • Each side will then engage in a constructive and respectful debate. Let’s rumble!</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>### FLNC Chat</span></span>
<span class="line"><span>chat page</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>🗽 Welcome to the FLNC chat 🇺🇸 Please introduce yourself AND provide a piece of value you think members around Liberty would benefit from. Resources, Tips, Recommendations, Opportunities</p><p>You may be invited to join more topic-focused irregularchats based on your hobbies and interests.</p><p>See all the community chats: <a href="https://forum.irregularchat.com/t/229/" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/229/</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### NCR Chat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>🏛️ Welcome to the National Capital Region chat 📜 Please introduce yourself AND provide a piece of value you think members around NCR would benefit from, such as Resources, Tips, Recommendations, Opportunities</p><p>You may be invited to join more topic-focused irregularchats based on your hobbies and interests.</p><p>See all the community chats: <a href="https://forum.irregularchat.com/t/229" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/229</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Central Texas Chat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>🌵 Welcome to the Texas Chat 🤠 Please introduce yourself AND share a piece of value you think members across Texas would benefit from—resources, tips, recommendations, or opportunities. Covering areas like San Antonio (SATX), Austin (ATX), Houston, and beyond, this is the place to connect with like-minded individuals in the Lone Star State.</p><p>You may be invited to join more topic-focused IrregularChats based on your hobbies and interests.</p><p>🔗 See all the community chats: <a href="https://forum.irregularchat.com/t/229/" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/229/</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Domestic Issues &quot;Politics” Chat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Welcome to the Domestic Issues Chat! Here, we tackle political, religious, and other partisan topics with open minds and respectful dialogue. While serious discussion is encouraged, satire, jokes, and memes related to these topics are also welcome.</p><p>Feel free to share your perspectives and engage in debates, but remember: thoughtful pushback is part of the conversation.</p><p>You can find previous topics here: <a href="https://forum.irregularchat.com/c/community/8" target="_blank" rel="noreferrer">https://forum.irregularchat.com/c/community/8</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Modern Warfare Chat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Welcome to the Modern Warfare Chat! This space is dedicated to UNCLASSIFIED discussing current and future conflicts, focusing on tactics, strategy, and warfighting at all levels.</p><p>Feel free to share insights, ask questions, or debate concepts related to modern warfare—from recent engagements to future battlegrounds.</p><p>Whether you&#39;re diving into real-world strategy or contemplating future warfare scenarios, this is the place for deep UNCLASSIFIED discussion and exploration.</p><p>There are separate chats for unmanned systems, RF/EW, Tech, AI, etc. <a href="https://forum.irregularchat.com/t/229/" target="_blank" rel="noreferrer">https://forum.irregularchat.com/t/229/</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>### Full Stack Chat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>🚀 Welcome to the Full Stack Chat! 🔧💻</p><p>This chat is for discussions on everything full-stack, covering: 🔹 System Administration &amp; Networking – Server setup, DevOps, cloud infrastructure, security best practices. 🔹 Backend Development – Automation, scripting, API design, database management. 🔹 Frontend Development – UI/UX, frameworks, web performance optimization.</p><p>💡 Please introduce yourself and drop in your GitHub username</p><p>📚 Community Resources: 🔗 IrregularChat GitHub: github.com/irregularchat 🔗 IrregularChat Hackathons: github.com/irregularchat</p><p>This is a space to collaborate, share knowledge, and build cool things together. Let’s code! 🚀</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,106)])])}const m=a(t,[["render",i]]);export{h as __pageData,m as default};
